interface SmsSender {
    void send(String phoneNumber, String message);
}

class TwilioSmsSender implements SmsSender {
    public void send(String phoneNumber, String message) {
        // appel à l'API Twilio
    }
}

// Le service ne dépend que du contrat SMS, pas d'un fournisseur multicanal complet
void notifyLateDelivery(SmsSender sms, String phone) {
    sms.send(phone, "Votre colis est retardé");
}

